    [1221337] = { en = "Deploy an emergency hiding spot. Most enemies will be less likely to notice you while you stand near it. Observant foes may not be so easily fooled.\r\n\r\nCannot be cast in combat.", description = "Piazza un nascondiglio d’emergenza. La maggior parte dei nemici farà più fatica a notarti se gli resti vicino, ma i più attenti potrebbero non farsi ingannare.\r\nNon può essere usato in combattimento." },
    [1222430] = { en = "Kel'Thuzad's body is rapidly decomposing, causing heavy damage over time.", description = "Il corpo di Kel'Thuzad si decompone rapidamente, infliggendo ingenti danni nel tempo." },
    [1222487] = { en = "Attempts to finish off a wounded enemy with a fatal strike.", description = "Tenta di finire un nemico ferito con un colpo mortale." },
    [1222772] = { en = "Light drives away the spirits and the darkness, affording some measure of safety.\r\n", description = "La luce respinge gli spiriti e l’oscurità, offrendo una certa protezione." },
    [1222951] = { en = "Light drives away the spirits and the darkness, affording some measure of safety.\r\n", description = "La luce respinge gli spiriti e l’oscurità, offrendo una certa protezione." },
    [1223311] = { en = "The way is lit. The path is clear. You require only the strength to follow it.", description = "La via è illuminata, il cammino è chiaro. Ti basta trovare la forza di seguirlo." },
    [1225291] = { en = "Nullify a nearby Naga power stone.", description = "Neutralizza una pietra del potere naga nelle vicinanze." },
    [1225458] = { en = "Hurls a bolt of light magic at an enemy, inflicting Holy damage.\r\n", description = "Scaglia un dardo di luce contro un nemico, infliggendo danni sacri." },
    [1225481] = { en = "Shoot down a Wasp Nest.", description = "Abbatti un nido di vespe." },
    [1225503] = { en = "Your class abilities no longer require reagents purchaseable from vendors.", description = "Le abilità della tua classe non richiedono più reagenti acquistabili dai mercanti." },
    [1225972] = { en = "Your tinker malfunction and caused an explosion.", description = "Il tuo congegno si è guastato provocando un’esplosione." },
    [1226402] = { en = "Steal an apple from a safe distance.", description = "Ruba una mela da una distanza di sicurezza." },
    [1226800] = { en = "Stash a piece of crafted Scarlet Crusade equipment in the crate. This will permanently destroy the item.", description = "Riponi nella cassa un pezzo d’equipaggiamento della Scarlet Crusade creato da te. L’oggetto verrà distrutto permanentemente." },
    [1227080] = { en = "Teaches you how to cook Carrie Hearthfire's most desirable feast recipes.", description = "Ti insegna a preparare le ricette più ambite del banchetto di Carrie Hearthfire." },
    [1227343] = { en = "Grants you permanent access to the New Avalon tavern without the need to carry a Haute Club Membership Card.\r\n\r\nYou must still be disguised to enter.", description = "Ti garantisce accesso permanente alla taverna di New Avalon senza dover portare con te una Haute Club Membership Card.\r\n\r\nDevi comunque essere travestito per entrare." },
    [1227358] = { en = "Briefly stunned by your own ineptitude.", description = "Sei stordito per un breve istante dalla tua stessa inettitudine." },
    [1227435] = { en = "Place targets into a deep sleep.", description = "Fa sprofondare i bersagli in un sonno profondo." },
    [1227772] = { en = "Shoot with determination and malicious intent.", description = "Spara con determinazione e intento malevolo." },
    [1228237] = { en = "Your ability to heal wounds is significantly reduced. ", description = "La tua capacità di curare le ferite è notevolmente ridotta." },
    [1228262] = { en = "Strikes at an enemy, inflicting increased melee damage and causing them to bleed.", description = "Colpisce un nemico, infliggendo danni da mischia maggiori e facendolo sanguinare." },
    [1228294] = { en = "Use the device at a designated triangulation point to aid Fizzlefuse in his teleporter's calibration.", description = "Usa il dispositivo in un punto di triangolazione designato per aiutare Fizzlefuse a calibrare il suo teletrasporto." },
    [1228331] = { en = "Allows the caster to move at extremely high speeds and perform devastating weapon attacks for a short time.\r\n", description = "Permette all’incantatore di muoversi a velocità elevatissima e sferrare devastanti attacchi con le armi per un breve periodo." },
    [1228369] = { en = "Charges a target.", description = "Carica un bersaglio." },
}

for id, description in pairs(verifiedSpellDescriptions) do
    ns.data.spellDescriptionOverrides[id] = description
    local entry = ns.data.spells[id]
    if type(entry) == "table" then
        entry.enDescription = description.en
        entry.description = description.description
    end
end
